import * as THREE from 'three';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

/**
 * OBJ Exporter for Three.js scenes with Blender Z-up conversion
 * Applies -90 degree X-rotation to convert from Three.js Y-up to Blender Z-up
 */
class OBJExporter {
  constructor() {
    this.output = '';
    this.vertexIndex = 1; // OBJ indices start at 1
    this.vertices = [];
    this.faces = [];
  }

  /**
   * Parse Three.js scene and convert to OBJ format
   */
  parse(object) {
    // Create rotation matrix for -90 degrees around X-axis (Y-up to Z-up)
    const rotationMatrix = new THREE.Matrix4();
    rotationMatrix.makeRotationX(-Math.PI / 2);

    // Traverse the scene hierarchy
    object.traverse((node) => {
      if (node.isMesh) {
        this.processMesh(node, rotationMatrix);
      } else if (node.isInstancedMesh) {
        this.processInstancedMesh(node, rotationMatrix);
      }
    });

    // Build OBJ output
    this.buildOutput();
    return this.output;
  }

  /**
   * Process a regular mesh
   */
  processMesh(mesh, rotationMatrix) {
    const geometry = mesh.geometry;

    // Get world matrix for this mesh
    mesh.updateMatrixWorld(true);
    const worldMatrix = mesh.matrixWorld.clone();

    // Apply Blender rotation after world transform
    worldMatrix.premultiply(rotationMatrix);

    // Clone geometry to avoid modifying original
    const geo = geometry.clone();

    // Ensure geometry has position attribute
    if (!geo.attributes.position) {
      console.warn(`Mesh "${mesh.name}" has no position attribute, skipping.`);
      return;
    }

    // Convert to non-indexed geometry for simplicity
    const nonIndexedGeo = geo.index ? geo.toNonIndexed() : geo;

    this.exportGeometry(nonIndexedGeo, worldMatrix, mesh.name);
  }

  /**
   * Process an instanced mesh by expanding all instances
   */
  processInstancedMesh(instancedMesh, rotationMatrix) {
    const geometry = instancedMesh.geometry;
    const count = instancedMesh.count;

    // Get world matrix for the instanced mesh parent
    instancedMesh.updateMatrixWorld(true);
    const parentWorldMatrix = instancedMesh.matrixWorld.clone();

    // Clone geometry
    const geo = geometry.clone();
    if (!geo.attributes.position) {
      console.warn(`InstancedMesh "${instancedMesh.name}" has no position attribute, skipping.`);
      return;
    }

    const nonIndexedGeo = geo.index ? geo.toNonIndexed() : geo;

    // Export each instance with its transform
    const instanceMatrix = new THREE.Matrix4();
    for (let i = 0; i < count; i++) {
      instancedMesh.getMatrixAt(i, instanceMatrix);

      // Combine: world transform → instance transform → Blender rotation
      const finalMatrix = new THREE.Matrix4();
      finalMatrix.copy(parentWorldMatrix);
      finalMatrix.multiply(instanceMatrix);
      finalMatrix.premultiply(rotationMatrix);

      const instanceName = `${instancedMesh.name}_instance_${i}`;
      this.exportGeometry(nonIndexedGeo, finalMatrix, instanceName);
    }
  }

  /**
   * Export geometry vertices and faces
   */
  exportGeometry(geometry, transformMatrix, objectName) {
    const positions = geometry.attributes.position;
    const vertexCount = positions.count;

    // Add object/group name
    this.output += `o ${objectName}\n`;
    this.output += `g ${objectName}\n`;

    const startIndex = this.vertexIndex;
    const vertex = new THREE.Vector3();

    // Export vertices with transform applied
    for (let i = 0; i < vertexCount; i++) {
      vertex.fromBufferAttribute(positions, i);
      vertex.applyMatrix4(transformMatrix);

      this.output += `v ${vertex.x.toFixed(6)} ${vertex.y.toFixed(6)} ${vertex.z.toFixed(6)}\n`;
    }

    // Export faces (triangles)
    // Since we converted to non-indexed geometry, every 3 vertices form a triangle
    for (let i = 0; i < vertexCount; i += 3) {
      const i1 = startIndex + i;
      const i2 = startIndex + i + 1;
      const i3 = startIndex + i + 2;
      this.output += `f ${i1} ${i2} ${i3}\n`;
    }

    this.vertexIndex += vertexCount;
  }

  /**
   * Build final OBJ output
   */
  buildOutput() {
    // OBJ header
    const header = `# OBJ File exported from Three.js\n`;
    const info = `# Converted to Blender Z-up coordinate system\n`;
    const separator = `# -------------------------------------\n\n`;

    this.output = header + info + separator + this.output;
  }
}

/**
 * Main export function
 */
function exportToOBJ() {
  console.log('Creating Three.js scene...');
  const scene = createScene();

  // Force update all matrices
  scene.updateMatrixWorld(true);

  console.log('Exporting to OBJ format...');
  const exporter = new OBJExporter();
  const objContent = exporter.parse(scene);

  // Write to output file
  const outputPath = path.join('/root/output/object.obj');
  fs.writeFileSync(outputPath, objContent, 'utf-8');

  console.log(`Successfully exported to: ${outputPath}`);
  console.log(`Total vertices: ${exporter.vertexIndex - 1}`);
  console.log('Coordinate system: Blender Z-up (applied -90° X-rotation)');
}

// Run the export
exportToOBJ();

